def f(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    mk=sorted(cnt.items(),key=lambda t:t[1])[0][0]   # rarest color = marker
    mark={(i,j) for i in range(H) for j in range(W) if g[i][j]==mk}
    from collections import defaultdict
    dd=defaultdict(list)
    for p in mark: dd[p[0]+p[1]].append(p)
    segs=[]
    for d,v in dd.items():
        v.sort(key=lambda p:p[0])
        cur=[v[0]]
        for q in v[1:]:
            if q[0]==cur[-1][0]+1 and q[1]==cur[-1][1]-1:
                cur.append(q)
            else:
                segs.append(cur); cur=[q]
        segs.append(cur)
    seg=max(segs,key=len)
    a,b=seg[0],seg[-1]
    dv,dw=b[0]-a[0],b[1]-a[1]
    def walk(stp,ddir=(dv,dw)):
        q=stp;n=0
        while True:
            q=(q[0]+ddir[0],q[1]+ddir[1]); n+=1
            if not(0<=q[0]<H and 0<=q[1]<W): return ('edge',n,q)
            if g[q[0]][q[1]]!=bg: return ('blk',n,q)
    r0=walk(a,(-dv,-dw)); r1=walk(b,(dv,dw))
    # prefer end whose walk stops at a blocker (reach obstacle rather than run to edge)
    def pref(r):
        return ('blk' if r[0]=='blk' else 'edge', r[1] if r[0]=='blk' else -1)
    vertices=[]
    for name,r in [('endA',r0),('endB',r1)]:
        if r[0]=='blk': vertices.append((name,r[1],pref(r)))
        elif r[0]=='edge': vertices.append((name,r[1],pref(r)))
    v=vertices[0][1] if len(vertices)==1 else None
    # if both reach blocker (both directions), prefer the one whose blocker is nearer
    if len(vertices)==2:
        vertices.sort(key=lambda t:t[2][1])
        v=vertices[0][1]
    res=[row[:] for row in g]
    res[v[0]][v[1]]=3
    i,j=v
    # continue incoming direction past vertex until blocked, then reflect
    # reflection: flip the component; choose candidate whose first step is free
    opts=[(-dv,-dw),(dv,-dw),(-dv,dw)]
    chosen=None
    for cand in opts:
        ni,nj=i+cand[0],j+cand[1]
        if 0<=ni<H and 0<=nj<W and g[ni][nj]==bg:
            chosen=cand;break
    ni,nj=i+chosen[0],j+chosen[1]
    while True:
        if not(0<=ni<H and 0<=nj<W) or g[ni][nj]!=bg: break
        res[ni][nj]=3; i,j=ni,nj
        ni,nj=i+chosen[0],j+chosen[1]
    return res
